// [S4] Three-portal family features — appointments list + cancel.
import 'package:family_veda/providers/family_portal_provider.dart';
import 'package:family_veda/widgets/shared/async_state_views.dart';
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:intl/intl.dart';

class AppointmentsScreen extends ConsumerWidget {
  const AppointmentsScreen({super.key});

  Future<void> _cancel(BuildContext context, WidgetRef ref, String id) async {
    try {
      await ref.read(familyPortalApiProvider).cancelAppointment(id);
      ref.invalidate(myAppointmentsProvider);
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(content: Text('Appointment cancelled.')),
        );
      }
    } on Object {
      if (context.mounted) {
        ScaffoldMessenger.of(context).showSnackBar(
          const SnackBar(
            content: Text('Could not cancel the appointment. Try again.'),
          ),
        );
      }
    }
  }

  @override
  Widget build(BuildContext context, WidgetRef ref) => Scaffold(
    appBar: AppBar(title: const Text('Appointments')),
    floatingActionButton: FloatingActionButton.extended(
      onPressed: () => context.push('/appointments/book'),
      icon: const Icon(Icons.add),
      label: const Text('Book'),
    ),
    body: SafeArea(
      child: ref
          .watch(myAppointmentsProvider)
          .when(
            loading: () => const LoadingStateView(label: 'Loading appointments'),
            error: (_, _) => ErrorRetryView(
              onRetry: () => ref.invalidate(myAppointmentsProvider),
            ),
            data: (items) => items.isEmpty
                ? EmptyStateView(
                    title: 'No appointments yet',
                    message: 'Book a visit with your family doctor.',
                    action: ElevatedButton(
                      onPressed: () => context.push('/appointments/book'),
                      child: const Text('Book appointment'),
                    ),
                  )
                : ListView.builder(
                    padding: const EdgeInsets.fromLTRB(16, 16, 16, 96),
                    itemCount: items.length,
                    itemBuilder: (context, index) {
                      final item = items[index];
                      return Card(
                        child: ListTile(
                          leading: const Icon(Icons.event_outlined),
                          title: Text(item.memberDisplayName),
                          subtitle: Text(
                            '${item.status.friendlyLabel}\n'
                            '${DateFormat.yMMMd().add_jm().format(item.startsAt)}'
                            '${item.doctor?.displayName != null ? '\nDr. ${item.doctor!.displayName}' : ''}',
                          ),
                          isThreeLine: true,
                          trailing: item.status.isCancellable
                              ? TextButton(
                                  onPressed: () => _cancel(context, ref, item.id),
                                  child: const Text('Cancel'),
                                )
                              : null,
                        ),
                      );
                    },
                  ),
          ),
    ),
  );
}
